import {
    MakeLogicType,
    actions,
    afterMount,
    connect,
    kea,
    listeners,
    path,
    reducers,
    selectors,
    sharedListeners,
} from 'kea'
import type { BreakPointFunction } from 'kea'

import { gravatarUrl, probeImage } from 'lib/utils/gravatar'
import { userLogic } from 'scenes/userLogic'

import { UserType } from '~/types'

export type GravatarStatus = 'unknown' | 'found' | 'missing'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface profilePictureLogicValues {
    user: UserType | null // userLogic
    gravatarChecking: boolean
    gravatarEmail: string | null
    gravatarRecheckCount: number
    gravatarStatus: GravatarStatus
    usesHedgehogAsProfilePicture: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface profilePictureLogicActions {
    checkGravatar: () => {
        value: true
    }
    recheckGravatar: () => {
        value: true
    }
    setGravatarStatus: (status: GravatarStatus) => {
        status: GravatarStatus
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface profilePictureLogicMeta {
    sharedListeners: {
        probeGravatar: (
            payload: any,
            breakpoint: BreakPointFunction,
            action: {
                type: string
                payload: any
            },
            previousState: any
        ) => void | Promise<void>
    }
    __keaTypeGenInternalSelectorTypes: {
        gravatarEmail: (user: UserType | null) => string | null
        usesHedgehogAsProfilePicture: (user: UserType | null) => boolean
    }
}

export type profilePictureLogicType = MakeLogicType<
    profilePictureLogicValues,
    profilePictureLogicActions,
    Record<string, any>,
    profilePictureLogicMeta
>

export const profilePictureLogic = kea<profilePictureLogicType>([
    path(['scenes', 'settings', 'user', 'profilePictureLogic']),
    connect(() => ({ values: [userLogic, ['user']] })),
    actions({
        checkGravatar: true,
        recheckGravatar: true,
        setGravatarStatus: (status: GravatarStatus) => ({ status }),
    }),
    reducers({
        gravatarStatus: [
            'unknown' as GravatarStatus,
            {
                setGravatarStatus: (_, { status }) => status,
            },
        ],
        gravatarChecking: [
            false,
            {
                checkGravatar: () => true,
                recheckGravatar: () => true,
                setGravatarStatus: () => false,
            },
        ],
        gravatarRecheckCount: [
            0,
            {
                recheckGravatar: (state) => state + 1,
            },
        ],
    }),
    selectors({
        gravatarEmail: [
            (s) => [s.user],
            (user: UserType | null): string | null => user?.email?.trim().toLowerCase() || null,
        ],
        usesHedgehogAsProfilePicture: [
            (s) => [s.user],
            (user: UserType | null): boolean => !!user?.hedgehog_config?.use_as_profile,
        ],
    }),
    sharedListeners(({ values, actions }) => ({
        probeGravatar: async (_, breakpoint) => {
            const email = values.gravatarEmail
            if (!email) {
                actions.setGravatarStatus('missing')
                return
            }
            const loaded = await probeImage(gravatarUrl(email))
            breakpoint()
            actions.setGravatarStatus(loaded ? 'found' : 'missing')
        },
    })),
    listeners(({ sharedListeners }) => ({
        checkGravatar: sharedListeners.probeGravatar,
        recheckGravatar: sharedListeners.probeGravatar,
    })),
    afterMount(({ actions }) => {
        actions.checkGravatar()
    }),
])
